--- src/checkout-total.mjs
   1: export function roundCurrency(value) {
   2:   return Math.round((value + Number.EPSILON) * 100) / 100;
   3: }
   4: 
   5: export function calculateCheckoutTotal(items, taxRate = 0) {
   6:   const subtotal = items.reduce(
   7:     (total, item) => total + roundCurrency(item.price * item.quantity),
   8:     0,
   9:   );
  10:   return roundCurrency(subtotal * (1 + taxRate));
  11: }
--- src/discount.mjs
   1: export function applyDiscount(amount, percentage) {
   2:   return amount * (1 - percentage / 100);
   3: }
--- src/shipping.mjs
   1: export function shippingCost(weightKg) {
   2:   return weightKg <= 2 ? 4.99 : 9.99;
   3: }
--- src/tax.mjs
   1: export function calculateTax(amount, rate) {
   2:   return Math.round(amount * rate * 100) / 100;
   3: }
